// ... остальные импорты
import MenuContent from './MenuContent'; // Импортируем новый компонент

export default function Header(): ReactElement {
  // ... все ваши хуки и функции остаются

  // Функция для клика по курсу
  const handlecourseClick = (courseId: string) => {
    console.log('Переключаемся на курс:', courseId);
    const params = new URLSearchParams(searchParams.toString());
    params.set('content', courseId);
    router.replace(`/?${params.toString()}`, { scroll: false });
    setIsMobileMenuOpen(false); // Закрываем мобильное меню
  };

  return (
    <header>
      <div className="logo-container">
        <img src={logo.src} alt="Logo" />
      </div>
      
      <div className='search-container'>
        {/* ... ваш поиск ... */}
      </div>

      {/* Кнопка гамбургера (только мобильная) */}
      {isMobileView && (
        <button 
          className="mobile-menu-toggle"
          onClick={() => setIsMobileMenuOpen(true)}
        >
          <img src={Icon_Hamburger.src} alt="Меню" />
        </button>
      )}

      {/* Десктопное меню (рендерим компонент) */}
      {!isMobileView && (
        <MenuContent
          isMobile={false}
          currentRouteId={currentRouteId}
          onCourseClick={handlecourseClick}
        />
      )}

      {/* Мобильная модалка (рендерим тот же компонент!) */}
      {isMobileMenuOpen && (
        <div className="mobile-menu-modal">
          <div className="mobile-menu-header">
            <button onClick={() => setIsMobileMenuOpen(false)}>
              <img src={Icon_Close.src} alt="Закрыть" />
            </button>
          </div>
          <div className="mobile-menu-content">
            <MenuContent
              isMobile={true}
              currentRouteId={currentRouteId}
              onCourseClick={handlecourseClick}
            />
          </div>
        </div>
      )}
    </header>
  );
}